// The MCP tools for a person's files: find, list, read, write, send in pieces, show, the ones used most recently
// (src/recent-files.mjs), what was worked out about them, and the facts kept about each (set_file_facts changes only
// the facts it names). Every tool reaches the namespace (src/namespace.mjs) through `call`, the same routes and the
// same plan check a key or an app sign-in reaches over HTTP (src/worker.mjs answerNamespace), so there is one owner of
// storage, dedupe and room, and no second way to store a file.
//
// Pictures: an AI app can look at a picture it is handed as an MCP `image` block, and shows a file to the person only
// through a view it draws (the MCP Apps standard: the tool names a `ui://` resource and the app loads it, which is how
// ChatGPT and Claude draw a tool's result). So read_file hands pictures over as images, every file answer carries a
// `resource_link` to the file, and show_file names the view that shows a picture, video or sound in the chat.
import { FILE_VIEW_DATA_KEY } from '../parts/ui/show/file-view-document/file-view-bridge.mjs';
import { fileViewDocument } from '../parts/ui/show/file-view-document/file-view-document.mjs';
import { withContent, withViewData } from './tool-reply.mjs';
import setAside from '../../recently-deleted-and-storage/namespace-set-aside.json' with { type: 'json' };
import byteRelease from './namespace-byte-release.json' with { type: 'json' };
import { ingestDecision } from './ingest-normalization.mjs';
import { FILE_LOOKUP_PATH, fileLookupBody } from './namespace-file-lookup.mjs';
import requestBody from './namespace-request-body.json' with { type: 'json' };

// The picture types AI apps accept as image content (MCP image blocks, model vision input).
const PICTURE_TYPES = new Set(['image/png', 'image/jpeg', 'image/gif', 'image/webp']);
// A picture up to this size is handed over whole as an image; a bigger one as a link.
const PICTURE_INLINE_MAX_BYTES = 3 * 1024 * 1024;
// One contents read returns at most this much.
const READ_MAX_BYTES = 262144;
// How long the address show_file hands the app keeps working.
const SHOW_SECONDS = 3600;
const VIEW_URI = 'ui://files/show-file.html';
const VIEW_MIME_TYPE = 'text/html;profile=mcp-app';
const VIEW_WORDS = { title: 'A file' };
// How much of a text file travels with show_file's result for its view to show (the view never has to read it).
const VIEW_TEXT_BYTES = 65536;

const mediaTypeOf = value => String(value ?? '').split(';')[0].trim().toLowerCase();
const isPicture = file => PICTURE_TYPES.has(mediaTypeOf(file?.media_type));
const fileCall = (asked, seconds) => [FILE_LOOKUP_PATH, fileLookupBody(asked, seconds ? { seconds } : {})];
const contentsCall = (asked, offset, length) => ['/namespace/contents/read', fileLookupBody(asked, { offset, length })];
// A finished upload's answer with what ingest does with a video (src/ingest-normalization.mjs); other files pass unchanged.
function withIngest(finished) {
  const decision = ingestDecision({ name: finished?.names?.[0] ?? finished?.name, media_type: finished?.media_type, byte_length: finished?.byte_length });
  return decision.said === null ? finished : { ...finished, ingest: decision };
}
const upload = id => `/namespace/growing/${encodeURIComponent(id)}`;

const bytesOfBase64 = text => Uint8Array.from(atob(text), character => character.charCodeAt(0));
function base64Of(bytes) {
  let binary = '';
  for (let at = 0; at < bytes.length; at += 0x8000) binary += String.fromCharCode(...bytes.subarray(at, at + 0x8000));
  return btoa(binary);
}

// The file's first name, else the name it was asked by, else its identity.
const labelOf = (found, asked) => found.names?.[0] ?? (asked?.startsWith('/') ? asked : found.identity);
// A link any MCP client can follow to read the file, until the address expires.
const linkTo = (found, asked) => found?.url ? { type: 'resource_link', uri: found.url, name: labelOf(found, asked).split('/').pop() || found.identity, ...(found.media_type ? { mimeType: mediaTypeOf(found.media_type) } : {}), description: `Reads ${labelOf(found, asked)} until ${found.url_expires_at}.` } : null;

// A whole picture as one image block, read a range at a time.
async function pictureBlock(call, asked, first = null) {
  const pieces = [];
  let read = first ?? await call(...contentsCall(asked, 0, READ_MAX_BYTES));
  for (let offset = 0; ;) {
    pieces.push(read.encoding === 'base64' ? bytesOfBase64(read.content) : new TextEncoder().encode(read.content));
    offset += read.bytes_returned;
    if (!read.bytes_returned || offset >= read.byte_length) break;
    read = await call(...contentsCall(asked, offset, READ_MAX_BYTES));
  }
  const bytes = new Uint8Array(pieces.reduce((sum, piece) => sum + piece.length, 0));
  pieces.reduce((at, piece) => { bytes.set(piece, at); return at + piece.length; }, 0);
  return { type: 'image', data: base64Of(bytes), mimeType: mediaTypeOf(read.media_type) };
}

async function readFile(call, asked, offset, length) {
  const read = await call(...contentsCall(asked, offset, length));
  if (!isPicture(read) || offset !== 0) return read;
  const found = await call(...fileCall(asked));
  // A picture too big to show whole says so, and how to fetch it, instead of leaving the AI to guess it was empty.
  if (read.byte_length > PICTURE_INLINE_MAX_BYTES) return withContent({ ...read, media_omitted: { reason: `larger than ${PICTURE_INLINE_MAX_BYTES} bytes`, fetch_by: asked, how: 'open the link, or read_file a range at a time' } }, [linkTo(found, asked)]);
  const { content, ...facts } = read;
  return withContent({ ...facts, bytes_returned: read.byte_length, encoding: 'image' }, [await pictureBlock(call, asked, read), linkTo(found, asked)]);
}

// The first part of a file as text, when its bytes are UTF-8 text: a read that stopped inside a character still counts,
// the cut character left out. Null for any other file, or when it could not be read.
async function firstTextOf(call, found) {
  let read;
  try { read = await call(...contentsCall(found.identity, 0, VIEW_TEXT_BYTES)); } catch { return null; }
  if (read.encoding !== 'base64') return { text: read.content, shown_bytes: read.bytes_returned, byte_length: read.byte_length };
  if (read.bytes_returned >= read.byte_length) return null;
  const bytes = bytesOfBase64(read.content);
  for (let cut = 1; cut <= 3; cut += 1) {
    try { return { text: new TextDecoder('utf-8', { fatal: true }).decode(bytes.subarray(0, bytes.length - cut)), shown_bytes: bytes.length - cut, byte_length: read.byte_length }; } catch {}
  }
  return null;
}

// The view reads a picture, video, sound or PDF from the file's address itself (elements the app's frame lets load),
// but a frame an AI app draws may refuse the view's own reads (ChatGPT does not always admit connectDomains), so a text
// file's first part travels with the result, in _meta, for the view alone, with the look the person wears now.
async function showFile(call, asked) {
  const found = await call(...fileCall(asked, SHOW_SECONDS));
  const shown = { name: labelOf(found, asked), identity: found.identity, media_type: found.media_type ?? null, byte_length: found.byte_length, url: found.url, url_expires_at: found.url_expires_at };
  const whole = !found.growing && found.byte_length > 0;
  const picture = isPicture(found) && found.byte_length <= PICTURE_INLINE_MAX_BYTES && whole ? await pictureBlock(call, asked) : null;
  const firstText = whole && !isPicture(found) ? await firstTextOf(call, found) : null;
  // The view wears the person's look at this moment, the same as every other screen of theirs (looks.mjs page).
  const look = await call('/looks/page').catch(() => null);
  const forView = { ...(firstText ? { first_text: firstText } : {}), ...(look ? { look } : {}) };
  return withViewData(withContent(shown, [picture, linkTo(found, asked)]), Object.keys(forView).length ? { [FILE_VIEW_DATA_KEY]: forView } : null);
}

// A file from the chat, as ChatGPT hands one to a tool that lists it in _meta "openai/fileParams": an address to read it
// from until it expires, and its own name and type.
const CHAT_FILE = { type: 'object', description: 'A file from this chat: {download_url, file_id}, as the app hands it over', properties: { download_url: { type: 'string' }, file_id: { type: 'string' }, mime_type: { type: 'string' }, file_name: { type: 'string' } }, required: ['download_url', 'file_id'], additionalProperties: false };
const pieceBytes = { content_base64: { type: 'string', description: 'The bytes, base64' }, text: { type: 'string', description: 'The bytes as UTF-8 text, instead of content_base64' } };

// Recently Deleted and Archived (src/namespace-set-aside.mjs): which states there are, and how an asked name or identity
// becomes one thing to take out of view.
const STATES = setAside.states.map(state => state.id);
const STATE_WORDS = setAside.states.map(state => `${state.id} (${state.label}: ${state.due_words.toLowerCase()} after its keep-for days)`).join('; ');
const asItems = list => (Array.isArray(list) ? list : []).map(asked => (String(asked).startsWith('/') ? { name: String(asked) } : { identity: String(asked) }));
const NAMES_OR_IDENTITIES = { type: 'array', minItems: 1, maxItems: setAside.items_per_request, items: { type: 'string' }, description: 'Path names (starting with /) of files or folders, or file content identities' };
const setAsideTool = (call, name, state, description) => ({ name, description, inputSchema: { type: 'object', required: ['names_or_identities'], properties: { names_or_identities: NAMES_OR_IDENTITIES } }, run: ({ names_or_identities }) => call('/namespace/set-aside', { items: asItems(names_or_identities), state }) });

export const fileTools = call => [
    { name: 'search', description: 'Searches everything this person keeps with one question: their files (the words written inside a document such as a PDF, Word, Excel, slides or text file, the words said in a recording, what is seen in it, its name and title, their notes), their Trillion records (decisions, pursuits, messages) and connected services such as GitHub. Ask it the person\'s own question ("what is my EIN") or the words to find. Each result is one thing with found_in (the places it matched: name, said, seen, written), said (the words around the match, which hold the answer), open_url (the address that opens the file in Trillion: give it to the person as the source link) and, for a recording, moments with start and end in seconds and the words said there, so a clip can be cut from them without guessing. To show a found file in this chat, call show_file with its identity. places (optional) keeps only those places, for example ["said"] for what is said or ["name"] for titles; sources (optional) keeps only those sources, for example ["files"]. unavailable names a place or source that could not answer and why; pending names one still working (searching what is seen starts a picture model once per question): ask again in a few seconds. find_file reaches a file by its exact name instead.', inputSchema: { type: 'object', required: ['question'], properties: { question: { type: 'string', maxLength: 500 }, places: { type: 'array', items: { type: 'string' } }, sources: { type: 'array', items: { type: 'string' } }, limit: { type: 'integer', minimum: 1, maximum: 200 } } }, run: ({ question, places, sources, limit }) => call(`/namespace/search?q=${encodeURIComponent(question ?? '')}${places?.length ? `&places=${encodeURIComponent(places.join(','))}` : ''}${sources?.length ? `&sources=${encodeURIComponent(sources.join(','))}` : ''}${limit ? `&limit=${limit}` : ''}`) },
    { name: 'manage_search_lanes', description: 'Looks after the index lanes behind search (the places a match can come from, such as the words in documents or the colours in pictures): action stats counts them (lane optional: every lane when left out) with whether each is on, its mode, what is still waiting and how many results it keeps (at_least N when the count was cut short); disable stops one lane being built and searched while keeping what it holds; enable puts it back and catches up on what changed meanwhile; prune forgets the results a lane holds a page at a time (call again while more is true) and rebuilds it once empty. lane is a lane id from stats. Only this person\'s own account can change lanes.', inputSchema: { type: 'object', required: ['action'], properties: { action: { type: 'string', enum: ['stats', 'enable', 'disable', 'prune'] }, lane: { type: 'string' } } }, run: ({ action, lane }) => call('/namespace/search-lanes', { action, ...(lane ? { lane } : {}) }) },
    { name: 'find_file', description: 'Finds one of this person\'s files in their namespace by its path name (starting with /) or its content identity (1f: or 12: then 64 hex). Returns the size, type, where it is kept, every name it has, and a url that reads it (ranges supported) until url_expires_at, plus its locator rows for any resolver.', inputSchema: { type: 'object', required: ['name_or_identity'], properties: { name_or_identity: { type: 'string' }, seconds: { type: 'integer', minimum: 60, maximum: 604800, description: 'How long the url keeps working (default 6 hours)' } } }, run: async ({ name_or_identity, seconds }) => { const found = await call(...fileCall(name_or_identity, seconds)); return withContent(found, [linkTo(found)]); } },
    { name: 'list_files', description: 'Lists one folder of this person\'s namespace: the folders inside it (folders), and each file named in it with its content identity and whether its bytes are stored (stored: true), or are still arriving (stored: false with uploading: its upload id, bytes_held and byte_length). A file that is one of several versions of the same file in that folder (the same name with a copy number, a version number, an export time or a backup mark) carries version { family, latest, latest_name, versions }: work from the one with latest: true, and the older ones stay there to go back to. A file whose same bytes are also kept under other names carries also_named (how many), so the same work is not done twice. Start at folder "/" and open a folder by passing its name as folder; pass next_after as after for the next page of files.', inputSchema: { type: 'object', properties: { folder: { type: 'string' }, after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ folder = '/', after = '', limit = 200 } = {}) => call('/namespace/listing', { collection: folder, after, limit }) },
    { name: 'copy_folder', description: 'Copies one of this person\'s folders, or their whole drive (from "/"), into another folder at once, by names only: every file under from gets the same name under to and points at the same bytes, so nothing is uploaded or stored twice and a copy of terabytes takes as long as writing its names. A name already used under to keeps what it holds; files still uploading are left out; to cannot be inside from. Answers copied and next_after: call again with after set to next_after until it is null. Changing a file in the copy later never changes the original.', inputSchema: { type: 'object', required: ['from', 'to'], properties: { from: { type: 'string', description: 'The folder to copy, starting with /' }, to: { type: 'string', description: 'The new folder, starting with /' }, after: { type: 'string' } } }, run: ({ from, to, after = '' }) => call('/namespace/fork', { from, to, after }) },
    { name: 'read_file', description: 'Reads what one of this person\'s files contains, by its path name (starting with /) or content identity: up to 256 KiB from offset, as text when those bytes are UTF-8 text and as base64 otherwise. Read longer files a range at a time. A picture (PNG, JPEG, GIF or WebP) up to 3 MiB comes back whole as an image you can look at, with a link to it; a bigger picture comes back as a link. Reading a file does not show it to the person: use show_file for that.', inputSchema: { type: 'object', required: ['name_or_identity'], properties: { name_or_identity: { type: 'string' }, offset: { type: 'integer', minimum: 0 }, length: { type: 'integer', minimum: 1, maximum: 262144 } } }, run: ({ name_or_identity, offset = 0, length = 65536 }) => readFile(call, name_or_identity, offset, length) },
    { name: 'files_summary', description: 'Counts this person\'s kept files, bytes and names, plus uploads in progress and unnamed files. The store\'s total database size is exact. Table names are included, while per-table rows and bytes are null because this ordinary summary does not scan every record or database page. record_history.head is the identity of the newest file of older record changes kept outside the store; each such file names the one before it, so the head shows none was changed or dropped. Needs nothing and changes nothing; list_files and find_file show the files themselves.', inputSchema: { type: 'object', properties: {} }, run: async () => ({ ...(await call('/namespace/summary')), uploads: (await call('/namespace/growing')).uploads, store: await call('/namespace/store-use'), record_history: await call('/namespace/history-head'), unnamed: await call('/namespace/unnamed?limit=20') }) },
    { name: 'read_file_results', description: 'Reads what has already been worked out about one of this person\'s files, by its content identity (1f: or 12: then 64 hex): its transcript, summary, measured facts, the folders it is filed in, and anything else a tool recorded. kind (optional) reads one of them. A read by any identity of the file finds results recorded under its others.', inputSchema: { type: 'object', required: ['identity'], properties: { identity: { type: 'string' }, kind: { type: 'string', description: 'For example transcript, summary, facts or folders' } } }, run: ({ identity, kind }) => call(`/namespace/results/${encodeURIComponent(identity)}${kind ? `?kind=${encodeURIComponent(kind)}` : ''}`) },
    { name: 'list_file_results', description: 'Lists one kind of result across every file in this person\'s namespace, a page at a time in identity order (pass next_after as after), so a filter or search can run over titles, summaries or facts without the files themselves. With no kind, returns how many results of each kind are kept.', inputSchema: { type: 'object', properties: { kind: { type: 'string' }, after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ kind, after = '', limit = 200 } = {}) => call(kind ? `/namespace/results?kind=${encodeURIComponent(kind)}&after=${encodeURIComponent(after)}&limit=${limit}` : '/namespace/results') },
    { name: 'record_file_results', description: 'Records what was worked out about files, so no AI has to work it out again: results is a list (at most 500) of { identity, kind, value, produced_by, only_if_absent }. identity is the file\'s content identity; kind names what the value is (transcript, summary, facts, folders or a new kind); value is any JSON. Set only_if_absent true to fill a missing result without replacing a concurrently saved result, including another identity for the same file. The same saved value remains an idempotent retry. Recording the same value again changes nothing.', inputSchema: { type: 'object', required: ['results'], properties: { results: { type: 'array', maxItems: 500, items: { type: 'object', required: ['identity', 'kind', 'value'], properties: { identity: { type: 'string' }, kind: { type: 'string' }, value: {}, produced_by: { type: 'string' }, only_if_absent: { type: 'boolean' } } } } } }, run: ({ results }) => call('/namespace/results', { results }) },
    { name: 'set_file_facts', description: 'Sets facts about one of this person\'s files, by its content identity (1f: or 12: then 64 hex), the way the person fills a column in Files and Media: facts is an object of the facts to set, and only those change; a fact set to null is taken away. Known facts: captured_at (when it was filmed or taken, as an ISO date and time), place (the place\'s name, such as "Lisbon"), location ({ latitude, longitude }), camera, duration (seconds) and resolution ("1920×1080"); any other name is one of the person\'s own fields (such as client or shot_type) and shows as a field they can filter by. Returns every fact the file now has. read_file_results with kind facts reads them.', inputSchema: { type: 'object', required: ['identity', 'facts'], properties: { identity: { type: 'string' }, facts: { type: 'object', description: 'The facts to set, by name; null takes one away' }, produced_by: { type: 'string' } } }, run: ({ identity, facts, produced_by }) => call(`/namespace/results/${encodeURIComponent(identity)}/merge`, { kind: 'facts', value: facts, ...(produced_by ? { produced_by } : {}) }) },
    { name: 'write_file', description: 'Saves a file in this person\'s namespace under name (a path starting with /, such as /edits/cover-cut.json), from exactly one of: text (UTF-8: a transcript, a note, an edit as JSON); content_base64 (a small file\'s bytes, at most 16 MiB); from_url (an https address that serves the file itself, which Trillion reads, any size); or file (a file from this chat, as the app hands it over: {download_url, file_id}). Never type a large file out as base64: give its address, or start_file_upload and send its bytes from your computer to send_bytes_to. With only file, name defaults to /<its file name>. media_type (optional) is its type, such as audio/mpeg or application/json; text without one is saved as text/plain. Returns the file\'s content identity (1f: then 64 hex), which run_tool accepts wherever a tool takes a file, and its name. Bytes this person already has are only given the name (already_kept: true). A name already in use then points at the new file; the earlier file stays readable by its identity.', inputSchema: { type: 'object', properties: { name: { type: 'string' }, ...pieceBytes, from_url: { type: 'string', description: 'An https address that serves the file itself; Trillion reads the bytes from it' }, file: CHAT_FILE, media_type: { type: 'string' } } }, _meta: { 'openai/fileParams': ['file'] }, run: input => call('/namespace/write', input) },
    { name: 'start_file_upload', description: 'Starts saving a file that is on a computer you can run commands on, or too big for one write_file call: name (a path starting with /), byte_length (its exact size in bytes) and media_type. Returns upload (its id), send_bytes_to and send_with: from that computer run curl -sS -T <file> "<send_bytes_to>" and the file is finished when its last byte arrives (a file over ' + requestBody.most_body_bytes + ' bytes goes in parts of at most that size, each with &offset=<its first byte>). Without a computer, send it with put_file_piece, piece 0 first (at most max_piece_bytes each), then finish_file_upload. Starting the same name again stops the earlier unfinished upload of that name. From its first piece the file can be found, read and played by its name while the rest arrives. If you know the file\'s BLAKE3 identity, give it as identity: a file this person already has is then only named (state: present) and nothing needs sending.', inputSchema: { type: 'object', required: ['name', 'byte_length'], properties: { name: { type: 'string' }, byte_length: { type: 'integer', minimum: 1 }, media_type: { type: 'string' }, identity: { type: 'string' } } }, run: ({ name, byte_length, media_type, identity }) => call('/namespace/growing', { name, byte_length, ...(media_type ? { media_type } : {}), ...(identity ? { identity } : {}) }) },
    { name: 'put_file_piece', description: 'Sends one piece of an upload from start_file_upload: piece is its number from 0, offset is where it starts in the file (the total size of the pieces before it), and its bytes as content_base64 (or text), at most max_piece_bytes. Pieces go in order; sending the same piece again changes nothing. Returns how many bytes the pieces now cover.', inputSchema: { type: 'object', required: ['upload', 'piece', 'offset'], properties: { upload: { type: 'string' }, piece: { type: 'integer', minimum: 0 }, offset: { type: 'integer', minimum: 0 }, ...pieceBytes } }, run: ({ upload: id, ...piece }) => call(`${upload(id)}/pieces`, piece) },
    { name: 'finish_file_upload', description: 'Completes an upload once its pieces cover the whole file, and returns the file with its content identity (1f: then 64 hex) and its names; a video that is not MP4 also returns ingest (convert, with the output name and ffmpeg arguments, or kept as it came, with why). identity (optional) is the file\'s BLAKE3 identity if you worked it out; left out, it is worked out from the stored bytes.', inputSchema: { type: 'object', required: ['upload'], properties: { upload: { type: 'string' }, identity: { type: 'string' } } }, run: async ({ upload: id, identity }) => withIngest(await call(`${upload(id)}/finish`, identity ? { identity } : {})) },
    { name: 'cancel_file_upload', description: 'Stops an upload from start_file_upload that will not be finished: its name is removed and the room it held is given back. Files already finished are not touched.', inputSchema: { type: 'object', required: ['upload'], properties: { upload: { type: 'string' } } }, run: ({ upload: id }) => call(upload(id), undefined, 'DELETE') },
    { name: 'list_note_tasks', description: 'Lists the checkbox tasks written in this person\'s notes (file results of kind note, notes or markdown), in note then written order. A task is a paragraph that starts with a checkbox: [ ] open or [x] done. Each carries item_id (result:<file identity>#<kind>; read the note with read_file_results), position, text, done and kind. done (optional) keeps only done (true) or open (false) tasks; after is the last item_id of the previous page.', inputSchema: { type: 'object', properties: { done: { type: 'boolean' }, kind: { type: 'string' }, space_id: { type: 'string' }, after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ done, kind, space_id, after, limit } = {}) => call(`/namespace/notes/tasks?${new URLSearchParams(Object.entries({ done, kind, space_id, after, limit }).filter(([, value]) => value !== undefined && value !== '').map(([key, value]) => [key, String(value)]))}`) },
    { name: 'list_note_tags', description: 'Lists the tags written in this person\'s notes with how many notes carry each. Tags are #tag, nested #work/project (children also count toward their parents) and #multi word tag#; matching is case-insensitive and display is the spelling first written.', inputSchema: { type: 'object', properties: { space_id: { type: 'string' }, after: { type: 'string', description: 'next_after from the page before' }, limit: { type: 'integer', minimum: 1 } } }, run: ({ space_id, after, limit } = {}) => call(`/namespace/notes/tags${new URLSearchParams(Object.entries({ space_id, after, limit }).filter(([, value]) => value !== undefined && value !== '')).toString().replace(/^(?=.)/, '?')}`) },
    { name: 'items_for_note_tag', description: 'Lists the notes that carry a tag or any tag beneath it (work also finds work/project), each with its item_id, kind and space_id so it can be opened.', inputSchema: { type: 'object', required: ['tag'], properties: { tag: { type: 'string' }, space_id: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ tag, space_id, limit } = {}) => call(`/namespace/notes/tags/${encodeURIComponent(tag)}?${new URLSearchParams(Object.entries({ space_id, limit }).filter(([, value]) => value !== undefined && value !== '').map(([key, value]) => [key, String(value)]))}`) },
    { name: 'sweep_content_tags', description: 'Gives automatic tags to one bounded page of this person\'s files that have a transcript, summary, facts or title kept, scored against the tag vocabulary (data, editable). Only files whose kept tags are older than the vocabulary or their evidence are redone, and a tag the person set is never removed or replaced. Answers tagged, skipped, failed and next_after: call again with next_after as after until it is null. Read the tags with read_file_tags or read_file_results kind tags.', inputSchema: { type: 'object', properties: { after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ after, limit } = {}) => call('/namespace/tags/sweep', { after, limit }) },
    { name: 'tag_file_now', description: 'Tags one file now from what is already kept about it (transcript, summary, facts, title) and returns its tags, each with source (auto or person) and score. The person\'s own tags stay.', inputSchema: { type: 'object', required: ['file'], properties: { file: { type: 'string', description: 'The file\'s path name (starting with /) or content identity' } } }, run: ({ file }) => call('/namespace/tags/tag', { file }) },
    { name: 'read_file_tags', description: 'Reads the tags one file has, each with source (auto: scored from its kept results, or person: set by the person) and score.', inputSchema: { type: 'object', required: ['file'], properties: { file: { type: 'string', description: 'The file\'s path name (starting with /) or content identity' } } }, run: ({ file }) => call('/namespace/tags/read', { file }) },
    { name: 'set_file_tag', description: 'Sets a tag on one file as the person\'s own (source person, score 1), or takes it away with on false. A later automatic re-tag never removes or rescores a tag set this way. Returns the file\'s tags.', inputSchema: { type: 'object', required: ['file', 'tag'], properties: { file: { type: 'string', description: 'The file\'s path name (starting with /) or content identity' }, tag: { type: 'string' }, on: { type: 'boolean', description: 'false takes the tag away (default true)' } } }, run: ({ file, tag, on }) => call('/namespace/tags/set', { file, tag, ...(on === undefined ? {} : { on }) }) },
    { name: 'content_tags_version', description: 'Says which tag vocabulary version and scorer the automatic tags are made with. A sweep redoes only the files kept under another version.', inputSchema: { type: 'object', properties: {} }, run: () => call('/namespace/tags/version') },
    { name: 'find_files_by_tag', description: 'Lists the files carrying a tag, a page at a time in identity order (pass next_after as after).', inputSchema: { type: 'object', required: ['tag'], properties: { tag: { type: 'string' }, after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 1000 } } }, run: ({ tag, after, limit }) => call(`/namespace/tags/find?${new URLSearchParams(Object.entries({ tag, after, limit }).filter(([, value]) => value !== undefined && value !== '').map(([key, value]) => [key, String(value)]))}`) },
    { name: 'propose_file_tidy', description: 'Suggests a title and/or a folder for some of this person\'s files, for them to accept or reject on their Tidy up screen: items is a list (at most 200) of { name, title, folder, evidence, reason }. name is the file\'s path (starting with /); title (optional) is a short plain title for what the file is; folder (optional) is the folder path it belongs in (an existing one, or a new one its words name); evidence lists the kinds of results already kept about the file that the suggestion comes from (read them first with read_file_results: transcript, summary, facts). The title and a new folder must be supported by those results\' words, or the suggestion is refused with why; a file with nothing kept about it needs a transcript or summary first (record_file_results). A newer suggestion for the same file replaces one still waiting. Nothing changes until the person accepts it and it is applied (apply_file_tidy).', inputSchema: { type: 'object', required: ['items'], properties: { items: { type: 'array', minItems: 1, maxItems: 200, items: { type: 'object', required: ['name', 'evidence'], properties: { name: { type: 'string' }, title: { type: 'string', maxLength: 160 }, folder: { type: 'string' }, evidence: { type: 'array', minItems: 1, items: { type: 'string' } }, reason: { type: 'string', maxLength: 1000 } } } } } }, run: ({ items }) => call('/namespace/tidy', { items }) },
    { name: 'list_file_tidy', description: 'Lists the title and folder suggestions for this person\'s files, newest first: each with its id, the file (name), the title and folder suggested, the results it cites (evidence), why, who suggested it, its state (review: waiting for the person; accepted; rejected; applied; stale: the file or what is known about it changed since, so it will not be applied; undone) and, once applied, the tidy-up it was part of. counts says how many are in each state; can_undo names the tidy-up undo_file_tidy would reverse. state (optional) keeps only one state.', inputSchema: { type: 'object', properties: { state: { type: 'string', enum: ['review', 'accepted', 'rejected', 'applied', 'stale', 'undone'] } } }, run: ({ state } = {}) => call(`/namespace/tidy${state ? `?state=${encodeURIComponent(state)}` : ''}`) },
    { name: 'apply_file_tidy', description: 'Applies the suggestions this person accepted as one tidy-up: each title is recorded as the file\'s title (kind title) and each file is moved into its folder by name (its bytes are not touched). Each is checked again first: a file renamed, moved or replaced since, what is known about it changed since, or a name already taken refuses that one (state stale, with why) and applies nothing for it. ids (optional) applies only those accepted suggestions; name (optional) names the tidy-up in the history (default: Tidy up N files). Returns the tidy-up and its name, how many were applied and which were refused.', inputSchema: { type: 'object', properties: { ids: { type: 'array', items: { type: 'string' } }, name: { type: 'string', maxLength: 120 } } }, run: ({ ids, name } = {}) => call('/namespace/tidy/apply', { ...(ids ? { ids } : {}), ...(name ? { name } : {}) }) },
    { name: 'organize_existing_files', description: 'Organizes one bounded page of files already kept in this person\'s namespace, using their names and kept results as evidence. It records searchable organization rows and gives unfiled root arrivals category folders while preserving folders the person chose. Call again with next_after as after until it is null. A provisional name does not claim to describe image pixels.', inputSchema: { type: 'object', properties: { after: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: 200 } } }, run: ({ after = '', limit = 100 } = {}) => call('/namespace/organize-existing', { after, limit }) },
    { name: 'undo_file_tidy', description: 'Undoes one tidy-up as a whole: id (optional, from file_tidy_history; the latest not undone when left out) names it. Every title goes back to what it was and every moved file goes back to its old name. Refused, changing nothing, when any of those files was renamed, moved or given another title since.', inputSchema: { type: 'object', properties: { id: { type: 'string' } } }, run: ({ id } = {}) => call('/namespace/tidy/undo', id ? { id } : {}) },
    { name: 'file_tidy_history', description: 'Lists this person\'s applied tidy-ups, newest first: when each was applied and undone, whether it is the one undo_file_tidy would reverse (can_undo), and for each file its name before and after and its title before and after.', inputSchema: { type: 'object', properties: { limit: { type: 'integer', minimum: 1, maximum: 50 } } }, run: ({ limit } = {}) => call(`/namespace/tidy/history${limit ? `?limit=${limit}` : ''}`) },
    setAsideTool(call, 'delete_file', 'deleted', `Deletes files or folders of this person's (by path name) or a recording with every name it has (by content identity): they leave Files, Media and search and go to Recently Deleted, where put_back_file brings them back until their keep-for days end (read_keep_for); then their names are gone for good. The bytes are not erased. Answers set_aside (each with its id, days_left and due_at) and refused (each with why, for example a file still uploading).`),
    setAsideTool(call, 'archive_file', 'archived', `Archives files, folders or recordings of this person's: like delete_file they leave Files, Media and search, but go to Archived, and move on to Recently Deleted only when Archived's keep-for days end (read_keep_for). put_back_file brings them back. Answers set_aside and refused as delete_file does.`),
    { name: 'list_recently_deleted', description: `Lists what this person deleted or archived, newest first: each with its id (for put_back_file), label, state, the names it had, where it was, when and by whom, and days_left before it moves on (null: kept until put back). state (optional) keeps one: ${STATE_WORDS}. Pass next_after's ms and id as after_ms and after_id for the next page. Also answers keep_for.`, inputSchema: { type: 'object', properties: { state: { type: 'string', enum: STATES }, after_ms: { type: 'integer' }, after_id: { type: 'string' }, limit: { type: 'integer', minimum: 1, maximum: setAside.list_limit } } }, run: ({ state, after_ms, after_id, limit } = {}) => call(`/namespace/set-aside?${new URLSearchParams({ ...(state ? { state } : {}), ...(after_ms !== undefined && after_id ? { after_ms: String(after_ms), after_id } : {}), ...(limit ? { limit: String(limit) } : {}) })}`) },
    { name: 'put_back_file', description: 'Puts back what this person deleted or archived, by the ids list_recently_deleted gives: every name it had comes back where it was. One whose name another file took in the meantime stays in Recently Deleted and says so.', inputSchema: { type: 'object', required: ['ids'], properties: { ids: { type: 'array', minItems: 1, maxItems: setAside.items_per_request, items: { type: 'string' } } } }, run: ({ ids }) => call('/namespace/set-aside/put-back', { ids }) },
    { name: 'read_keep_for', description: `Reads how many days this person's Recently Deleted and Archived keep things before they move on (after_days, null: until put back), each state's default, and the usual choices. States: ${STATE_WORDS}.`, inputSchema: { type: 'object', properties: {} }, run: () => call('/namespace/keep-for') },
    { name: 'set_keep_for', description: `Changes how many days a state keeps things: after_days is { state: days } (a whole number from 0 to ${setAside.max_days}, or null to keep until put back). It applies at once to everything already there, so a shorter time can make things move on (or be gone for good) at the next sweep. States: ${STATE_WORDS}.`, inputSchema: { type: 'object', required: ['after_days'], properties: { after_days: { type: 'object', additionalProperties: { type: ['integer', 'null'], minimum: 0, maximum: setAside.max_days } } } }, run: ({ after_days }) => call('/namespace/keep-for', { after_days }) },
    { name: 'read_storage', description: 'How much storage this person\'s files use and when the storage of what they deleted is given back: kept (bytes and files, by the store that keeps them), waiting (what is in Recently Deleted and Archived), leaving (bytes that leave each day for the next days), each waiting item with when it leaves and which rule or keep-for decides it, given_back (bytes already given back, in all and per day), and their release rules. It changes nothing.', inputSchema: { type: 'object', properties: {} }, run: () => call('/namespace/storage') },
    { name: 'set_release_rules', description: `Replaces this person's release rules: when the storage of what they deleted is given back sooner than keep-for. Each rule is { id, label, on, when, after_days, storage_above_bytes, order }: when is a formula-engine rule tree { kind: "group", combinator: "and" | "or", negate: false, rules: [{ kind: "rule", field, operator, params }] } over the item facts ${byteRelease.item_facts.map(fact => `${fact.id} (${fact.kind})`).join(', ')}, or null for everything; after_days gives matching items back that many days after they were deleted; storage_above_bytes gives matching items back (order: ${byteRelease.orders.map(order => order.id).join(' or ')}) while the files kept are above that many bytes. Keep-for (set_keep_for) stays the longest anything waits. Read read_storage first and send the whole list. Answers what read_storage answers.`, inputSchema: { type: 'object', required: ['rules'], properties: { rules: { type: 'array', items: { type: 'object' } } } }, run: ({ rules }) => call('/namespace/release-rules', { rules }) },
    { name: 'release_deleted_files', description: 'Deletes for good what this person\'s release rules say leaves now (or, with rules, what those rules say; they are not saved) and gives its storage back. dry_run true only lists what would leave. A schedule or rule of theirs can run it as tool:release-deleted-files. Answers leaving (each item, its size and the rule that decided it) and bytes.', inputSchema: { type: 'object', properties: { rules: { type: 'array', items: { type: 'object' } }, dry_run: { type: 'boolean' } } }, run: input => call('/namespace/release', input ?? {}) },
    { name: 'recent_files', description: 'Lists the files this person used most recently, newest first, the same list as their Recent screen: each file once, with its identity, name, title, media_type, what happened last (last_kind, such as opened, watched, edited or published, and last_words, how the screen says it), when (last_at) and the newest time of every kind of use (kinds). Use it to pick up where the person left off. before (next_before from an earlier page) reads older files; limit caps how many (default 100). It changes nothing.', inputSchema: { type: 'object', properties: { limit: { type: 'integer', minimum: 1, maximum: 500 }, before: { type: 'string' } } }, run: ({ limit, before } = {}) => call(`/recent-files?${new URLSearchParams(Object.entries({ limit, before }).filter(([, value]) => value !== undefined && value !== null).map(([key, value]) => [key, String(value)]))}`) },
    { name: 'record_file_use', description: 'Keeps that this person used one of their files, so it rises to the top of their Recent screen and of recent_files: file is its path name (starting with /) or content identity, and kind says what happened in one short lowercase word or words joined by dashes (opened, watched, edited, published, or any other, such as sent-to-a-client). Record it when you open, play, change or publish a file for them. Trillion stamps the time; the same use again only moves the time.', inputSchema: { type: 'object', required: ['file', 'kind'], properties: { file: { type: 'string' }, kind: { type: 'string', pattern: '^[a-z][a-z0-9-]{0,39}$' } } }, run: ({ file, kind }) => call('/recent-files', { file, kind }) },
    { name: 'show_file', description: 'Shows one of this person\'s files to them in this chat, by its path name (starting with /) or content identity: a picture, video or sound appears in the conversation where the app draws tool results, from an address that works for an hour. A picture up to 3 MiB is also handed to you as an image. Use it whenever the person should see a file, such as a picture or video a tool made; describing a file does not show it.', inputSchema: { type: 'object', required: ['name_or_identity'], properties: { name_or_identity: { type: 'string' } } }, _meta: { ui: { resourceUri: VIEW_URI }, 'openai/outputTemplate': VIEW_URI, 'openai/toolInvocation/invoking': 'Opening the file', 'openai/toolInvocation/invoked': 'Showing the file' }, run: ({ name_or_identity }) => showFile(call, name_or_identity) },
];

