/** The views the file tools name, as MCP resources. `origin` is where the file addresses point, the one place the
 * view may load a file from. */
export const fileResources = origin => [{
  uri: VIEW_URI, name: 'show-file', title: 'Show a file', mimeType: VIEW_MIME_TYPE,
  // The view's script and look are the workspace's own build (scripts/build-workspace.mjs), served from this origin.
  text: () => fileViewDocument({ words: VIEW_WORDS, scriptUrl: `${origin}/workspace/file-view.js`, stylesheetUrl: `${origin}/workspace/workspace.css` }),
  _meta: { ui: { csp: { resourceDomains: [origin], connectDomains: [origin], frameDomains: [origin] }, prefersBorder: false }, 'openai/widgetCSP': { resource_domains: [origin], connect_domains: [origin], frame_domains: [origin] }, 'openai/widgetDescription': 'Shows the file the tool opened.' },
}];
